module max_chessmen(\n    input [15:0] n,\n    input [15:0] m,\n    output reg [31:0] result\n);\n    wire [15:0] n_min = (n < m) ? n : m;\n    wire [15:0] n_max = (n < m) ? m : n;\n\n    always @(*) begin\n        if (n_min == 16'd1) begin\n            reg [15:0] remainder = n_max % 16'd6;\n            reg [31:0] min_val = (remainder < 16'd3) ? remainder : (16'd6 - remainder);\n            result = n_max - min_val;\n        end\n        else if (n_min == 16'd2) begin\n            case (n_max)\n                16'd2: result = 32'd0;\n                16'd3: result = 32'd4;\n                16'd7: result = 32'd12;\n                default: result = 32'd2 * n_max;\n            endcase\n        end\n        else begin\n            result = n_min * n_max;\n            if (n_min[0] && n_max[0]) begin\n                result = result - 32'd1;\n            end\n        end\n    end\nendmodule